constexpr int factorial(int n) {
  return (n == 0) ? 1 : n * factorial(n - 1);
}

int main() {
  constexpr int result = factorial(5); // Compile-time calculation
  int runtime_result = factorial(5); // Runtime calculation (though compiler may optimize)
  constexpr int array[factorial(4)] = {}; // Compile-time array size
  return 0;
}
